CREATE TABLE authz_capabilities (id TEXT PRIMARY KEY, description TEXT, category TEXT); CREATE TABLE authz_roles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT UNIQUE NOT NULL, rank INTEGER NOT NULL DEFAULT 0, is_preset BOOLEAN DEFAULT false); CREATE TABLE authz_role_capabilities (role_id UUID REFERENCES authz_roles(id) ON DELETE CASCADE, capability_id TEXT REFERENCES authz_capabilities(id) ON DELETE CASCADE, PRIMARY KEY (role_id, capability_id)); CREATE TABLE authz_user_roles (user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE, role_id UUID REFERENCES authz_roles(id) ON DELETE CASCADE, PRIMARY KEY (user_id, role_id)); CREATE TYPE authz_effect AS ENUM ('ALLOW', 'DENY'); CREATE TABLE authz_user_exceptions (user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE, capability_id TEXT REFERENCES authz_capabilities(id) ON DELETE CASCADE, effect authz_effect NOT NULL, PRIMARY KEY (user_id, capability_id)); INSERT INTO authz_capabilities (id, description, category) VALUES ('league:edit_settings', 'Change league name', 'League'), ('roster:edit_player', 'Update players', 'Roster'), ('roster:manage_access', 'Manage access', 'Roster'), ('games:score_match', 'Score match', 'Games'), ('games:edit_history', 'Edit history', 'Games'), ('authz:manage_roles', 'Manage roles', 'Authz'), ('authz:assign_roles', 'Assign roles', 'Authz'), ('audit:view_all', 'View audit', 'Audit'); INSERT INTO authz_roles (name, rank, is_preset) VALUES ('League Admin', 100, true), ('Game Admin', 50, true), ('Referee', 20, true), ('Player', 0, true);
